package com.andye.warmod.radar.client;
import com.andye.warmod.WarMod;import com.andye.warmod.radar.client.gui.RadarScreen;import com.mojang.blaze3d.platform.InputConstants;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.minecraft.client.*;import net.minecraft.resources.Identifier;
public final class RadarKeyBindings{private static KeyMapping OPEN;private static boolean registered;private RadarKeyBindings(){}public static void register(){if(registered)return;KeyMapping.Category category=KeyMapping.Category.register(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"radar"));OPEN=new KeyMapping("key.war_mod.open_radar",InputConstants.Type.KEYSYM,77,category);ClientTickEvents.END_CLIENT_TICK.register(client->{while(OPEN.consumeClick()){if(client.gui.screen() instanceof RadarScreen)client.gui.setScreen(null);else ClientRadarNetworking.requestOpen();}});registered=true;}}
